import type { Metadata } from "next";
import { Dancing_Script, Outfit } from "next/font/google";
import "./globals.css";

const dancingScript = Dancing_Script({
  variable: "--font-cursive",
  subsets: ["latin"],
});

const outfit = Outfit({
  variable: "--font-sans",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Us Cutie 💖",
  description: "A romantic digital scrapbook of our love story.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body
        className={`${outfit.variable} ${dancingScript.variable} font-sans antialiased bg-[#FFF9F9] text-[#4A4A4A]`}
      >
        {children}
      </body>
    </html>
  );
}
